frappe.ui.form.on('Lead', {
    // Triggered when the sustain field is changed
    status: function(frm) {
        // Check if the sustain field has a value
        if (!frm.doc.sustain) {
            // Define the parameters for the API call
            const limit = "2025-02-20"; // Limit of items to fetch
            const offset = "2025-02-25"; // Starting point for pagination
            const user = "Mbale Gas Store - SE"; // Example user (can be dynamic as needed)

            // Make the API call to fetch item details
            frappe.call({
                method: 'petro_station_app.custom_api.gas_invoice.stock_balances.fetch_actual_qty_grouped_by_warehouse',
                args: {
                     warehouse_filter:"Mbale Gas Store"
                
                },
                callback: function(response) {
                    console.log(response)
               
                },
                error: function(error) {
                    // Handle API call failure
                    frappe.msgprint(__('Failed to fetch item details.'));
                    console.error('Error fetching item details:', error);
                }
            });
        }
    }
});

frappe.ui.form.on('Sales Order', {
    refresh: function (frm) {
        frm.add_custom_button('Send WhatsApp Template', function () {
            const phone_number = frm.doc.test_tels;  // Replace with your phone field

            frappe.call({
                method: 'gormsolutions_mobile_app.custom_api.whatsapp_api.api.send_whatsapp_template',
                args: {
                    to: phone_number
                },
                callback: function (response) {
                    if (response.message.status === "success") {
                        frappe.msgprint(response.message.message);
                    } else {
                        frappe.msgprint("Failed to send WhatsApp template message.");
                    }
                }
            });
        });
    }
});
